def double_elements(lst: list[int]) -> list[int]:
    """Return a new list with each integer element doubled."""
    return [x * 2 for x in lst]

def filter_even_numbers(lst: list[int]) -> list[int]:
    """Return a new list containing only the even numbers from the input list."""
    return [x for x in lst if x % 2 == 0]

def capitalize_words(s: str) -> str:
    """Return the string with each word capitalized."""
    return " ".join(word.capitalize() for word in s.split())

def sum_of_squares_of_odds(lst: list[int]) -> int:
    """Return the sum of the squares of the odd numbers in the list."""
    return sum(x * x for x in lst if x % 2 != 0)
